<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { Popup as VanPopup, showConfirmDialog } from 'vant'
import { useJournal, clone, errorMessage } from '../stores/journal'
import { amountText, cents, id, localDate, money, recurringDates, validDate, type RecurringRule } from '../domain'

const store = useJournal(), router = useRouter(), editor = ref<RecurringRule | null>(null), amount = ref(''), error = ref(''), working = ref(false), history = ref(false)
const rules = computed(() => store.data.rules.filter(r => !r.deleted)), periods = computed(() => store.data.occurrences.filter(o => history.value ? o.state !== 'pending' : o.state === 'pending').sort((a, b) => a.dueDate.localeCompare(b.dueDate)))
const preview = computed(() => { if (!editor.value || !validDate(editor.value.firstDate)) return []; const date = new Date(store.today + 'T12:00:00'); date.setFullYear(date.getFullYear() + 5); return recurringDates(editor.value, localDate(date)).filter(d => d >= store.today).slice(0, 5) })
const categoryName = (value: string) => store.data.categories.find(c => c.id === value)?.name ?? '未分类'
function edit(rule?: RecurringRule) { editor.value = rule ? clone(rule) : { id: id(), name: '', type: 'expense', categoryId: store.data.categories.find(c => c.type === 'expense')?.id ?? '', amountCents: 0, remark: '', frequency: 'month', firstDate: store.today, endDate: '', enabled: true, resumeFrom: store.today }; amount.value = rule ? amountText(rule.amountCents) : ''; error.value = '' }
async function save() { if (!editor.value || working.value) return; working.value = true; try { editor.value.amountCents = cents(amount.value); editor.value.name = editor.value.name.trim(); await store.saveRule(editor.value); editor.value = null } catch (reason) { error.value = errorMessage(reason) } finally { working.value = false } }
async function toggle(rule: RecurringRule) { try { await store.saveRule({ ...rule, enabled: !rule.enabled }) } catch (reason) { store.notify(errorMessage(reason)) } }
async function remove(rule: RecurringRule) {
  const count = store.pending.filter(o => o.ruleId === rule.id).length
  try { await showConfirmDialog({ title: `删除“${rule.name}”规则？`, message: `保留${count}个已有待确认项及全部历史账单，停止生成新期次。` }) } catch { return }
  try { await store.deleteRule(rule.id) } catch (reason) { store.notify(errorMessage(reason)) }
}
async function skip(periodId: string) { try { await store.skipOccurrence(periodId) } catch (reason) { store.notify(errorMessage(reason)) } }
const back = (event: Event) => { if (editor.value) { event.preventDefault(); if (!working.value) editor.value = null } }
onMounted(() => window.addEventListener('journal-back', back)); onUnmounted(() => window.removeEventListener('journal-back', back))
</script>
<template>
  <header class="page-header"><div><h1>周期账单</h1><p class="muted">到期提示，确认后才入账</p></div><button class="icon-button" @click="router.push('/ledger')">‹</button></header>
  <button class="primary full" @click="edit()">＋ 新建周期规则</button>
  <div v-for="rule in rules" :key="rule.id" class="panel stack compact-stack"><div class="row"><h2>{{ rule.name }}</h2><span>{{ rule.enabled ? '启用' : '暂停' }}</span></div><p>{{ rule.frequency === 'month' ? '每月' : '每年' }} · {{ rule.type === 'income' ? '收入' : '支出' }} ¥{{ money(rule.amountCents) }} · {{ categoryName(rule.categoryId) }}</p><p class="muted">首次 {{ rule.firstDate }}{{ rule.endDate ? ` · 截止 ${rule.endDate}` : '' }}</p><div class="toolbar"><button class="secondary" @click="edit(rule)">编辑</button><button class="secondary" @click="toggle(rule)">{{ rule.enabled ? '暂停' : '继续' }}</button><button class="danger" @click="remove(rule)">删除规则</button></div></div>
  <div class="tabs"><button :class="{ active: !history }" @click="history = false">待确认 {{ store.pending.length }}</button><button :class="{ active: history }" @click="history = true">处理历史</button></div><p class="muted">待确认与跳过项不计入收支；打开应用会补齐到期项。</p>
  <div v-for="period in periods" :key="period.id" class="panel stack compact-stack"><h2>{{ period.name }}</h2><p>{{ period.dueDate }} · {{ categoryName(period.categoryId) }} · {{ period.type === 'income' ? '+' : '−' }}{{ money(period.amountCents) }}</p><div v-if="period.state === 'pending'" class="toolbar"><button class="primary" @click="router.push({ path: '/ledger', query: { period: period.id } })">确认入账</button><button class="secondary" @click="skip(period.id)">跳过本次</button></div><button v-else-if="period.state === 'skipped'" class="secondary" @click="skip(period.id)">已跳过 · 恢复待确认</button><template v-else><button v-if="store.data.entries.some(e => e.id === period.entryId && !e.deletedAt)" class="secondary" @click="router.push({ path: '/ledger', query: { entry: period.entryId } })">已入账 · 查看账单</button><p v-else class="muted">已处理 · 关联账单已移入回收站或永久删除，不重复生成</p></template></div><p v-if="!periods.length" class="empty">暂无{{ history ? '处理历史' : '待确认项' }}</p>
  <VanPopup :show="!!editor" position="bottom" round :close-on-click-overlay="!working" @update:show="value => { if (!value && !working) editor = null }"><section v-if="editor" class="sheet"><form class="stack" @submit.prevent="save"><h2>周期规则</h2><fieldset :disabled="working" class="stack plain-fieldset"><label>名称<input v-model="editor.name" maxlength="100" required></label><div class="pair"><label>收支类型<select v-model="editor.type" @change="editor.categoryId = store.data.categories.find(c => c.type === editor?.type)?.id ?? ''"><option value="expense">支出</option><option value="income">收入</option></select></label><label>金额（元）<input v-model="amount" inputmode="decimal" required></label></div><label>分类<select v-model="editor.categoryId" required><option v-for="category in store.data.categories.filter(c => c.type === editor?.type)" :key="category.id" :value="category.id">{{ category.name }}</option></select></label><label>备注<textarea v-model="editor.remark" maxlength="500" rows="2"></textarea></label><label>重复<select v-model="editor.frequency"><option value="month">每月</option><option value="year">每年</option></select></label><div class="pair"><label>首次日期<input v-model="editor.firstDate" type="date" min="1900-01-01" required></label><label>截止日期（可不填）<input v-model="editor.endDate" type="date" :min="editor.firstDate"></label></div><p class="muted">接下来：{{ preview.join('、') || '暂无到期日' }}。缺少对应日时取月末。</p><p v-if="error" class="field-error">{{ error }}</p><button class="primary">保存规则</button><button type="button" class="secondary" @click="editor = null">取消</button></fieldset></form></section></VanPopup>
</template>
